config.code:
// Email classification engine
const subject = inputData.emailSubject || '';
const body = inputData.emailBody || '';

// Sentiment Analysis
let sentiment = 'neutral';
const positive = ['great', 'excellent', 'amazing', 'love', 'wonderful', 'best'];
const negative = ['terrible', 'horrible', 'awful', 'hate', 'angry', 'worst'];

if (positive.some(w => body.toLowerCase().includes(w))) sentiment = 'positive';
if (negative.some(w => body.toLowerCase().includes(w))) sentiment = 'negative';

// Intent Classification
let intent = 'other';
if (/support|help|bug|error|issue|problem|down|broken/i.test(body)) intent = 'support';
else if (/price|cost|billing|charge|invoice|refund/i.test(body)) intent = 'billing';
else if (/buy|purchase|subscription|upgrade|quote/i.test(body)) intent = 'sales';
else if (/feature|feedback|suggestion|idea|recommend/i.test(body)) intent = 'feedback';

// Priority Scoring
let priority = 'low';
if (/urgent|critical|emergency|asap|immediately|down|broken/i.test(body)) priority = 'high';
else if (sentiment === 'negative' || intent === 'support' || intent === 'billing') priority = 'medium';

// Department Routing
const routing = {
  high: { email: 'urgent@company.com', prefix: '[URGENT]' },
  support: { email: 'support@company.com', prefix: '[SUPPORT]' },
  billing: { email: 'billing@company.com', prefix: '[BILLING]' },
  sales: { email: 'sales@company.com', prefix: '[SALES]' },
  feedback: { email: 'feedback@company.com', prefix: '[FEEDBACK]' },
  other: { email: 'info@company.com', prefix: '[INFO]' }
};

let dept = routing[intent] || routing.other;
if (priority === 'high') dept = routing.high;

return {
  sentiment: sentiment,
  intent: intent,
  priority: priority,
  routingEmail: dept.email,
  prefix: dept.prefix,
  confidence: 0.95
};

